CREATE TABLE IF NOT EXISTS intent_research_runs (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, client_id INTEGER, audience_id INTEGER, provider TEXT NOT NULL DEFAULT 'manual', status TEXT NOT NULL DEFAULT 'completed', idempotency_key TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 1, retry_of_id INTEGER, requested_by INTEGER, summary JSONB NOT NULL DEFAULT '{}', error TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS intent_research_runs_tenant_key_uq ON intent_research_runs(tenant_id,idempotency_key);
CREATE INDEX IF NOT EXISTS intent_research_runs_tenant_status_idx ON intent_research_runs(tenant_id,status,started_at);
CREATE TABLE IF NOT EXISTS intent_evidence (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, signal_id INTEGER, research_run_id INTEGER, account_id INTEGER, contact_id INTEGER, product_id INTEGER, evidence_kind TEXT NOT NULL, event_type TEXT, event_fingerprint TEXT, source_url TEXT, excerpt TEXT, provider TEXT NOT NULL, confidence INTEGER NOT NULL DEFAULT 50 CHECK(confidence BETWEEN 0 AND 100), context JSONB NOT NULL DEFAULT '{}', raw_evidence JSONB NOT NULL DEFAULT '{}', review_status TEXT NOT NULL DEFAULT 'approved', reviewed_by INTEGER, reviewed_at TIMESTAMPTZ, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS intent_evidence_tenant_fingerprint_uq ON intent_evidence(tenant_id,event_fingerprint) WHERE event_fingerprint IS NOT NULL;
CREATE INDEX IF NOT EXISTS intent_evidence_tenant_account_product_idx ON intent_evidence(tenant_id,account_id,product_id,occurred_at);
CREATE INDEX IF NOT EXISTS intent_evidence_tenant_review_idx ON intent_evidence(tenant_id,review_status,created_at);
CREATE TABLE IF NOT EXISTS intent_contact_discovery_runs (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, client_id INTEGER, audience_id INTEGER, provider TEXT NOT NULL DEFAULT 'manual', criteria JSONB NOT NULL DEFAULT '{}', idempotency_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'preview', requested_by INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS intent_contact_discovery_runs_tenant_key_uq ON intent_contact_discovery_runs(tenant_id,idempotency_key);
CREATE TABLE IF NOT EXISTS intent_contact_discovery_candidates (id SERIAL PRIMARY KEY, tenant_id INTEGER NOT NULL, run_id INTEGER NOT NULL, company_id INTEGER, first_name TEXT, last_name TEXT, email TEXT, phone TEXT, title TEXT, function TEXT, location TEXT, source_url TEXT, provider TEXT NOT NULL, confidence INTEGER NOT NULL DEFAULT 50 CHECK(confidence BETWEEN 0 AND 100), raw_evidence JSONB NOT NULL DEFAULT '{}', match_status TEXT NOT NULL DEFAULT 'pending_review', canonical_contact_id INTEGER, reviewed_by INTEGER, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS intent_discovery_candidates_tenant_run_idx ON intent_contact_discovery_candidates(tenant_id,run_id,match_status);